.pdl-root .n3286_4803{word-break:break-word;display:flex;flex-direction:column;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:620;justify-content:center;line-height:26px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-point, #2b7fca);font-size:25px;letter-spacing:-0.5px;white-space:nowrap;width:204px}
.pdl-root .x9{line-height:26px}
